INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'Personal Data Protection Law — Official English Text', 'النص الرسمي لـ PDPL: نطاق البيانات الشخصية، الموافقة، تحديد الغرض، جمع وإفصاح محدود، حقوق أصحاب البيانات، إتلاف البيانات، قيود التسويق، وتعويضات.', 'https://sdaia.gov.sa/en/SDAIA/about/Documents/Personal%20Data%20English%20V2-23April2023-%20Reviewed-.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'نظام حماية البيانات الشخصية — المرسوم الملكي M/19', 'النظام الشامل لحماية البيانات الشخصية. بيانات الاستهلاك المنزلي المرتبطة بعداد/حساب قابلة للتعريف تُعد بيانات شخصية. سريان كامل من سبتمبر 2024.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Article 5 Consent', 'لا تُعالج البيانات الشخصية دون موافقة إلا في الحالات النظامية. Wafir يستخدم موافقة صريحة موثّقة كضبط خصوصية (privacy-by-design) وليس ادعاءً أن كل kWh حساسة دائماً.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL2/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Article 6 Legal Bases', 'أسس معالجة بدون موافقة: مصلحة مشروعة، تنفيذ عقد، التزام نظامي. تحليل الميزانية قد يستند للعقد؛ التحليلات الإضافية تتطلب أساساً منفصلاً.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL2/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Purpose Limitation (Arts. 10–13)', 'المعالجة لغرض محدد؛ تغيير الغرض يتطلب أساساً قانونياً. إعادة استخدام بيانات الاستهلاك للإعلانات دون موافقة/أساس منفصل يخالف تحديد الغرض.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Article 26 Direct Marketing', 'التسويق المباشر يتطلب موافقة وآلية إلغاء. PDPL لا يحظر كل تسويق مطلقاً — لكن إعادة غرض الاستهلاك للإعلانات دون أساس منفصل مرفوضة في Wafir (SC-03).', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL2/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA / Wafir', 'Wafir policy — no ads from consumption data', 'سياسة خصوصية Wafir: لا إعادة استخدام بيانات الاستهلاك للإعلانات المستهدفة دون أساس قانوني وموافقة منفصلة. SC-03 يحجب targeted_ads_from_consumption (VIOLATION/BLOCK_DATA_USE) — أقوى من الحد الأدنى النظامي.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Pseudonymization for ML export', 'إخفاء الهوية الحقيقي يتطلب استحالة إعادة التعريف. تجزئة household إلى معرف مجهول (pseudonymization) تبقى ضمن نطاق PDPL — لا تُسمّى anonymization تلقائياً.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PersonalDataDestruction/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Cross-Border Data Transfers', 'نقل البيانات خارج المملكة يخضع لضوابط PDPL (كفاية، SCC/BCR، أو استثناءات نظامية). يجب توثيق الأساس عند استضافة سحابة خارج KSA.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL2/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'PDPL — Complaints and Compensation', 'حق الشكوى للجهة المختصة؛ غرامات إدارية؛ حق التعويض المادي أو المعنوي عن ضرر من مخالفة PDPL.', 'https://sdaia.gov.sa/en/SDAIA/about/Documents/Personal%20Data%20English%20V2-23April2023-%20Reviewed-.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'Rules for Registration in National Register of Controllers', 'تسجيل المتحكمين في المنصة الوطنية؛ إخطار SDAIA بخرق البيانات خلال 72 ساعة عند الاقتضاء.', 'https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/Rulesandguidelinesp2/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SERA', 'SERA Personal Data Protection Policy', 'هيئة تنظيم الكهرباء: جمع الحد الأدنى من البيانات بموافقة واستخدامها للأغراض المصرّح بها فقط؛ إفصاح طرف ثالث بحدود الموافقة.', 'https://www.sera.gov.sa/en/knowledge-center/data-management-office/data-management-office-categories/office-policies/office-policies-3') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'AI Ethics Principles (Version 1.0)', 'عدالة، خصوصية، إنسانية، منفعة، موثوقية، شفافية وتفسير، مساءلة. لا خداع؛ إشراف بشري للقرارات عالية المخاطر. التوقعات تقديرية — ليست ضماناً مالياً.', 'https://dgp.sdaia.gov.sa/wps/wcm/connect/4c56ed1c-1b82-447d-ac29-638f5f99c12e/ai-principles-EN.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'Generative AI Guidelines for Government', 'إفصاح المحتوى المولّد بالذكاء الاصطناعي؛ مراجعة بشرية للمخرجات المؤثرة؛ آليات استشهاد للتحقق.', 'https://sdaia.gov.sa/en/SDAIA/about/Files/GenAIGuidelinesForGovernmentENCompressed.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'Generative AI Guidelines for Public (SDAIA-P115E)', 'تخفيف الهلوسة، الاستشهاد بالمصادر، الإشراف البشري في الواجهات المحادثية. يدعم نمط RAG في Wafir.', 'https://sdaia.gov.sa/en/SDAIA/about/Files/GenerativeAIPublicEN.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'AI Adoption Framework', 'إطار وطني لتبني AI متوافق مع أخلاقيات AI وPDPL.', 'https://sdaia.gov.sa/en/SDAIA/about/Files/AIAdoptionFramework.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SDAIA', 'SDAIA — Human oversight', 'إيقاف التنبيهات مؤقتاً (HITL ساعتين) في Wafir؛ تدخل بشري عند نزاع التقدير.', 'https://dgp.sdaia.gov.sa/wps/wcm/connect/4c56ed1c-1b82-447d-ac29-638f5f99c12e/ai-principles-EN.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Open Banking Framework', 'مشاركة بيانات الحسابات المصرفية بموافقة المستهلك. بيانات العداد/الاستهلاك ليست Open Banking data.', 'https://openbanking.sama.gov.sa/index-en.html') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Issues Open Banking Framework', 'إصدار الإطار: AIS ثم PIS ضمن استراتيجية FinTech.', 'https://www.sama.gov.sa/en-us/mediacenter/news/pages/news-794.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Open Banking — PIS and Lab', 'خدمات بدء الدفع (PIS) ومختبر الامتثال التقني للبنوك وTPPs.', 'https://www.sama.gov.sa/en-US/MediaCenter/News/pages/news-1135.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'Payments and Payment Services Law — Implementing Regulations', 'AISP يقتصر على حسابات الدفع والمعاملات المرتبطة — لا يشمل قراءات العداد الذكي.', 'https://rulebook.sama.gov.sa/en/implementing-regulations-payments-and-payment-services-law') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'Financial Consumer Protection Principles and Rules', 'معيار analog لـ Wafir (ليس التزاماً مباشراً ما لم يكن التطبيق تحت إشراف SAMA): إفصاح واضح، عدم تضليل، تحذيرات مخاطر.', 'https://rulebook.sama.gov.sa/en/financial-consumer-protection-principles-and-rules') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Cybersecurity Framework — Governance', 'مرجع عند تكامل مالي مستقبلي: نضج Level 3 Defined كحد أدنى للقطاع المالي.', 'https://www.sama.gov.sa/en-US/MediaCenter/News/Pages/news22042019.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SAMA', 'SAMA Cybersecurity Framework — Operations & Cloud', 'تشفير، IAM، إدارة مخاطر موردين وسحابة — مرجع لتكامل بنكي لاحق.', 'https://www.sama.gov.sa/en-US/MediaCenter/News/Pages/news22042019.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('CMA', 'CMA FinTech Lab', 'المختبر لأنشطة أسواق المال/الأوراق المالية. تطبيق ميزانية كهرباء منزلية ليس ضمن نطاق CMA على الوصف الحالي.', 'https://cma.gov.sa/en/Market/fintech/Pages/default.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SERA', 'SERA Residential Consumption Tariff', 'سكني: 18 هللة/ك.و.س (1–6000 ك.و.س/شهر)، 30 هللة فما فوق. مُطبّق في financial-engine.ts مع ضريبة 15% ورسوم عداد.', 'https://www.sera.gov.sa/en/consumer/electric-tariff/electric-tariff-categories/consumption-tariff') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SEC', 'SEC Consumption Tariffs', 'صفحة SEC للتعرفة السكنية بشرائح الاستهلاك — يجب جلب القيم الحالية من SERA/SEC وليس افتراض ثابت.', 'https://www.se.com.sa/en/Ourservices/ColumnC/Bills-and-Consumption/ConsumptionTariffs/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SERA / SEC', 'Small-Scale Solar PV Net-Billing', 'أنظمة شمسية منزلية: تصدير فائض بـ 0.07 ر.س/ك.و.س؛ خصم من فاتورة الاستيراد.', 'https://www.se.com.sa/-/media/92776F079FC043719013D4B05DDD49C6.ashx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SEC', 'Saudi Energy Data Sharing Policy', 'إطار مشاركة بيانات الشركة — لا يثبت API عام لتفويض المستهلك لتطبيقات طرف ثالث لقراءات العداد.', 'https://www.se.com.sa/en/Open-Data/Data-Sharing/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SEC', 'SEC Meter Declaration', 'إثبات علاقة المستخدم بالعداد (مالك/مستأجر) — شرط منطقي قبل معالجة بيانات العداد، دون أن يعني API عام.', 'https://www.se.com.sa/en/Ourservices/ColumnB/Account-Management/Account-Registration/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SEC', 'Saudi Electricity Company Portal', 'مزوّد الكهرباء الوطني؛ خدمات العداد والفوترة.', 'https://www.se.com.sa/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('SASO / SEEC', 'SASO 2663:2021 — Residential Air Conditioners', 'معايير كفاءة المكيفات السكنية؛ أساس لنصائح ترقية المعدات في RAG.', 'https://saso.gov.sa/en/mediacenter/news/Pages/saso_news_873.aspx') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAPSARC', 'KBEAT — Building Energy Assessment Tool', 'تحليل استهلاك المباني السكنية؛ نصائح نوعية: تقليل مدة التبريد، كفاءة المكيف، عزل، LED — دون ادعاء درجة حرارة محددة غير موثّقة.', 'https://apps.kapsarc.org/appboard/kbeat/en') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAPSARC', 'KAPSARC — Cooling Sustainability in KSA', 'المساحة المبردة، إعداد الترموستات، مدة التشغيل، كفاءة الوحدة، سلوك المستخدم — عوامل رئيسية لاستهلاك التكييف.', 'https://www.kapsarc.org/newsroom/news/with-saudi-arabia-s-g20-presidency-kapsarc-explores-ways-to-achieve-cooling-sustainability-and-increase-the-efficiency-of-ac-in-the-kingdom/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('Peer-reviewed / PMC', 'Residential Envelope and AC Measures (Saudi context)', 'عزل SBC-602 ومكيفات عالية الكفاءة تقلل استهلاك التبريد بشكل ملموس في سياق سعودي.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10098615/') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KAPSARC', 'KAPSARC DP00503 — Energy and AI', 'كفاءة الطاقة وتطبيقات الذكاء الاصطناعي في قطاع الطاقة.', 'https://www.kapsarc.org/media/ip0dt4i1/dp00503-v1.pdf') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('MDPI Energies', 'ML energy forecasting in KSA', 'مرجع أكاديمي لتوقعات استهلاك الطاقة.', 'https://www.mdpi.com/1996-1073/16/4/2035') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KSA / Umm Al-Qura', 'Civil Transactions Law — Harmful Acts', 'كل خطأ يسبب ضرراً للغير يلزم بالتعويض — أساس عام للمسؤولية؛ لا قاعدة خاصة بتوقعات AI للفاتورة.', 'https://www.uqn.gov.sa/details?p=23125') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('KSA / Umm Al-Qura', 'Civil Transactions Law — Compensation', 'التعويض لإصلاح الضرر بالكامل بما فيه الضرر المعنوي والكسب الفائت الناتج طبيعياً عن الفعل الضار.', 'https://www.uqn.gov.sa/details?p=23125') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('ITU-T', 'ITU-T Y.3172', 'خط أنابيب ML: SRC, C, PP, M, P, D, SINK, MLFO, Sandbox. P يطبّق سياسات حتمية على مخرجات النموذج.', 'https://www.itu.int/rec/T-REC-Y.3172-201906-I') ON CONFLICT DO NOTHING;
INSERT INTO regulation_chunks (source, title, content, url) VALUES ('ISO/IEC', 'ISO/IEC 42001:2023 — AI Management System', 'معيار دولي لحوكمة مخاطر AI — مرجع benchmark وليس قانون سعودي.', 'https://www.iso.org/standard/81230.html') ON CONFLICT DO NOTHING;
